{
  "name": "projects",
  "fields": [
    {
      "name": "id",
      "type": "uuid",
      "primaryKey": true,
      "nullable": false
    },
    {
      "name": "name",
      "type": "varchar",
      "length": 255,
      "nullable": false
    },
    {
      "name": "status",
      "type": "varchar",
      "length": 40,
      "nullable": true,
      "default": "active"
    },
    {
      "name": "budget",
      "type": "numeric",
      "precision": 12,
      "scale": 2,
      "nullable": true
    },
    {
      "name": "clientId",
      "type": "uuid",
      "nullable": true
    },
    {
      "name": "createdAt",
      "type": "timestamptz",
      "nullable": false
    }
  ]
}
